Bytes digest(std::string_view s){return sha256(Bytes(s.begin(),s.end()));}
Json tok(const ForkCheckpointToken& t){return {{"sequence",quantity(Int(std::to_string(t.sequence)))},{"digest",hex(t.digest)}};}
Json snapshot(const BeaconJournalIdentity& id){return {{"format","nano-beacon-signing-v1"},{"publicKey",hex(id.public_key)},{"genesisValidatorsRoot",hex(Bytes(id.genesis_validators_root.begin(),id.genesis_validators_root.end()))},{"slotsPerEpoch",quantity(Int(std::to_string(id.slots_per_epoch)))},{"proposal",nullptr},{"attestation",nullptr}};}
BeaconJournalPairInput pair(const Json& p,const Json& c,uint64_t sequence=7){
 const auto a=p.dump(),b=c.dump();const ForkCheckpointToken pt{sequence,digest(a)},next{sequence+(a==b?0:1),digest(b)};
 const auto intent=Json{{"format","nano-beacon-signing-witness-v1"},{"previous",a==b?Json(nullptr):tok(pt)},{"next",tok(next)},{"snapshot",b}};
 // Completed seq>1 still has a canonical direct predecessor, not a null origin.
 auto j=intent;if(a==b&&sequence>1)j["previous"]=tok({sequence-1,Bytes(32,0x22)});
 const auto w=j.dump();ForkCheckpointToken wt{11,digest(w)};return {{pt,a},{wt,w},pt,wt,std::nullopt,std::nullopt};
}
